import math
def is_prime(n):
  for i in range(2,int(math.sqrt(n))+1):
    if (n%i) == 0:
      return False
  return True
while True:
    n = input("Enter a number to check if it is prime. [Press 0 to exit]")
    if n == 0:
        print("Exiting the program.")
        break
    is_prime(n)

